// HLSL (per pixel). Input: scRGB linear FP16, 1.0 = 80 nits (BT.709 primaries).
float3 rec709_to_rec2020(float3 v) {
    return float3(dot(v, float3(0.62740389593469903, 0.32928303837788370, 0.043313065687417225)),
                  dot(v, float3(0.069097289358232075, 0.91954039507545871, 0.011362315566309178)),
                  dot(v, float3(0.016391438875150280, 0.088013307877225749, 0.89559525324762401)));
}
float linear_to_st2084_channel(float x) {            // x in units of 10000 nits
    float c = pow(abs(x), 0.1593017578);
    return pow((0.8359375 + 18.8515625 * c) / (1. + 18.6875 * c), 78.84375);
}
// ...
float3 rgb2020 = max(rec709_to_rec2020(scrgb.rgb), 0.0);   // negative = out of BT.2020 gamut -> clip
float3 pq      = saturate(float3(linear_to_st2084_channel(rgb2020.r * 80.0 / 10000.0),
                                 linear_to_st2084_channel(rgb2020.g * 80.0 / 10000.0),
                                 linear_to_st2084_channel(rgb2020.b * 80.0 / 10000.0)));
// BT.2020 non-constant-luminance, limited range, 10-bit (store <<6 for P010)
float Y  = 0.2627 * pq.r + 0.6780 * pq.g + 0.0593 * pq.b;
float Cb = (pq.b - Y) / 1.8814;
float Cr = (pq.r - Y) / 1.4746;
uint y10  = (uint)round(64.0  + 876.0 * Y);
uint cb10 = (uint)round(512.0 + 896.0 * Cb);
uint cr10 = (uint)round(512.0 + 896.0 * Cr);   // subsample Cb/Cr 2x2 (average) for 4:2:0
